begin;

do $$
declare
  v_sector uuid;
  v_category uuid;
  v_body jsonb;
  v_text text;
  v_id uuid;
begin
  select id into v_sector from public.sectors where slug='addiction-recovery';
  select id into v_category from public.categories where slug='addiction-community-systems' and sector_id=v_sector;
  if v_sector is null or v_category is null then raise exception 'peer support taxonomy missing'; end if;

  v_body := jsonb_build_object('blocks', jsonb_build_array(
    jsonb_build_object('type','paragraph','text','دعم الأقران في التعافي من اضطرابات استخدام المواد ليس علاجًا طبيًا بديلًا ولا صداقة غير منظمة، بل خدمة أو علاقة دعم تستفيد من الخبرة المعيشة بطريقة مقصودة ومحددة الأدوار. يستطيع الشخص الذي عاش تجربة التعافي أن يقدّم نوعًا من الفهم والأمل والمساندة العملية يصعب أحيانًا الحصول عليه من علاقة سريرية وحدها، بينما يبقى التشخيص ووصف الأدوية وإدارة الحالات الطبية والنفسية المعقدة ضمن مسؤولية المختصين المؤهلين. هذا المرجع يشرح كيف يعمل دعم الأقران، كيف نبني رأس مال التعافي، وما الحدود التي تحمي الشخص والعامل بالخدمة والمؤسسة.'),
    jsonb_build_object('type','paragraph','text','تؤكد SAMHSA في كفاءاتها المحدثة للعاملين بالأقران أن الخدمة ينبغي أن تكون موجهة نحو التعافي، متمحورة حول الشخص، طوعية، قائمة على العلاقة ومراعية للصدمة. هذه المبادئ مهمة لأنها تمنع تحويل الخبرة الشخصية إلى وصفة عامة. ما ساعد شخصًا واحدًا قد لا يناسب غيره، والمسار الذي يقوم على دواء أو علاج نفسي أو مجموعة دعم أو دين أو رياضة أو عمل أو أكثر من عنصر يمكن أن يكون مشروعًا ما دام آمنًا ومناسبًا له. وظيفة القرين هي توسيع الخيارات وربط الشخص بموارده وأهدافه، لا فرض نسخة من قصة التعافي الخاصة به.'),

    jsonb_build_object('type','heading','level',2,'text','1. ما دعم الأقران وما الذي يميزه عن العلاج والصداقة؟'),
    jsonb_build_object('type','paragraph','text','العامل بالأقران يستخدم خبرة معيشة ذات صلة، تدريبًا مناسبًا، مهارات استماع وتواصل، ومعرفة بالخدمات لمساعدة شخص آخر على التحرك نحو أهداف يختارها. قد يعمل في مركز علاج، مستشفى، رعاية أولية، منظمة تعافٍ مجتمعية، سكن تعافٍ، برنامج إعادة دخول بعد الاحتجاز، أو خدمة متنقلة أو رقمية. تختلف المسميات والقواعد القانونية باختلاف البلد، لذلك يجب على المؤسسة تحديد نطاق الدور بوضوح. وجود خبرة معيشة وحده لا يجعل كل شخص مؤهلًا للعمل المهني بالأقران، كما أن الشهادة وحدها لا تعوض غياب الإشراف والحدود الأخلاقية.'),
    jsonb_build_object('type','paragraph','text','الفرق عن الصداقة أن العلاقة المهنية لها غرض وحدود وتوثيق وإشراف وسياسات خصوصية. والفرق عن العلاج السريري أن العامل بالأقران لا يحوّل خبرته إلى تشخيص ولا يصف علاجًا ولا يفسر الأعراض الطبية كخبير سريري ما لم يكن يحمل مؤهلًا مستقلًا لذلك ويعمل ضمنه. والفرق عن الرعاية الإدارية أن قيمة الدور ليست فقط إعطاء عنوان خدمة؛ بل بناء الثقة، مساعدة الشخص على صياغة هدف، إزالة عائق عملي، الاستعداد لموعد، وربط الموارد بحياة الشخص الفعلية.'),

    jsonb_build_object('type','heading','level',3,'text','خمسة مبادئ تحكم العلاقة المهنية بالأقران'),
    jsonb_build_object('type','paragraph','text','أولًا التعافي ممكن وله مسارات متعددة. ثانيًا الشخص هو صاحب الهدف والخطة وليست الخدمة صاحبة الحياة. ثالثًا المشاركة طوعية ولا تتحول إلى عقوبة أو شرط إذعان. رابعًا العلاقة المبنية على الاحترام والثقة والتعاطف هي أداة أساسية وليست مجرد مقدمة. خامسًا الممارسة المراعية للصدمة تركز على الأمان والاختيار وعدم إعادة إنتاج السيطرة. إذا تعارضت سياسة المؤسسة مع هذه المبادئ، مثل مطالبة العامل بإجبار المستفيد على هدف لم يختره أو استخدام المعلومات التي شاركها في الثقة لمعاقبته دون مسوغ سلامة أو قانون، فالمشكلة في تصميم الخدمة لا في مهارة العامل فقط.'),

    jsonb_build_object('type','heading','level',2,'text','2. رأس مال التعافي: الموارد التي تجعل الاستمرار ممكنًا'),
    jsonb_build_object('type','paragraph','text','يستخدم TIP 64 مفهوم رأس مال التعافي لوصف كمية ونوعية الموارد التي يستطيع الشخص الاستفادة منها لبدء التعافي واستمراره. بعض الموارد شخصية مثل الصحة والمهارات والمعرفة والقدرة على التنظيم، وبعضها اجتماعي مثل العلاقات الداعمة، وبعضها مادي مثل السكن والنقل والدخل والوثائق، وبعضها مجتمعي أو ثقافي مثل الانتماء والخدمات والفرص والهوية والمعنى. القيمة في المفهوم أنه ينقل السؤال من ما الذي ينقص الشخص؟ إلى ما الذي يملكه الآن، وما الذي يمكن بناؤه، وما الحواجز التي تمنع استخدام موارده؟'),
    jsonb_build_object('type','paragraph','text','لا ينبغي تحويل رأس مال التعافي إلى امتحان استحقاق. الشخص الذي لا يملك سكنًا أو عملًا أو شبكة دعم لا يحتاج رعاية أقل بل غالبًا يحتاج تنسيقًا أكبر. كما أن المورد ليس إيجابيًا لمجرد وجوده؛ علاقة أسرية قد تكون داعمة أو مسيطرة، ومجموعة اجتماعية قد تدعم التعافي أو تعيد الشخص إلى بيئة عالية الخطر. لذلك يُفهم كل مورد بحسب وظيفته الفعلية وتفضيل الشخص، ويعاد تقييمه مع تغير الحياة.'),

    jsonb_build_object('type','heading','level',3,'text','خريطة رأس مال التعافي دون تحويلها إلى درجة'),
    jsonb_build_object('type','list','ordered',false,'items',jsonb_build_array(
      'الصحة: رعاية أولية وصحة نفسية ونوم وألم وأدوية وخطة متابعة مفهومة.',
      'السكن والاحتياجات الأساسية: مكان آمن ومستقر قدر الإمكان، غذاء، وثائق، نقل وقدرة على الوصول.',
      'العلاقات: أشخاص يحترمون الحدود ويدعمون الأهداف دون إذلال أو سيطرة.',
      'التعلم والعمل: مهارات وفرص وتعليم أو تدريب وعمل يتوافق مع مرحلة التعافي.',
      'المجتمع والهوية: انتماء ثقافي أو ديني أو تطوعي أو رياضي أو إبداعي يضيف معنى واتصالًا.',
      'الخدمات: علاج مناسب، دعم أقران، مجموعات اختيارية، مساعدة قانونية أو اجتماعية عند الحاجة.',
      'المهارات الشخصية: طلب المساعدة، حل المشكلات، إدارة الوقت والمال والضغط، والتعامل مع التعثر.'
    )),
    jsonb_build_object('type','paragraph','text','الخريطة تستخدم للحوار والتخطيط، لا للمقارنة بين الناس. يمكن للشخص أن يختار مجالين أو ثلاثة لهما أكبر أثر حالي بدل محاولة إصلاح الحياة كلها دفعة واحدة. إذا كان انقطاع النقل يمنع الدواء والمواعيد، فقد يكون حل النقل أكثر تأثيرًا من إضافة جلسة أخرى. وإذا كانت العزلة هي المشكلة، فقد يصبح بناء علاقة أو نشاط منتظم أولوية. العمل بالأقران قوي عندما يحوّل الهدف المجرد إلى خطوة مرتبطة بعائق واقعي.'),

    jsonb_build_object('type','heading','level',2,'text','3. خطة التعافي: يقودها الشخص وتراجع مع تغير الحياة'),
    jsonb_build_object('type','paragraph','text','يفرق TIP 64 بين خطة العلاج التي تركز غالبًا على أهداف سريرية وخطة التعافي الأوسع التي يقودها الشخص وتركز على العافية والاستدامة والحياة. يمكن للعامل بالأقران أن يساعد في صياغة أهداف قصيرة وطويلة المدى، ترتيب الأولويات، تقسيم الخطوات، تحديد الموارد والمسؤوليات، وموعد المراجعة. لا يحتاج الهدف إلى أن يكون كبيرًا؛ حضور موعد، استعادة وثيقة، العودة إلى فصل دراسي، إصلاح نوم، التواصل مع شخص داعم، أو بناء روتين صباحي قد تكون خطوات ذات معنى إذا كانت مرتبطة بما يريده الشخص.'),
    jsonb_build_object('type','paragraph','text','الخطة ليست عقدًا لإثبات الطاعة. يجب أن تتغير عندما تظهر معلومات جديدة أو يتغير السكن أو العمل أو الصحة أو العلاقات أو هدف الشخص. إذا لم تُنفذ خطوة، لا يبدأ التقييم بسؤال لماذا لم يلتزم؟ بل ما العائق؟ هل كانت الخطوة كبيرة؟ هل لم تكن أولوية حقيقية؟ هل تغير الخطر؟ هل الخدمة نفسها صعبة الوصول؟ هذه اللغة تحافظ على المسؤولية دون تحويل التعثر إلى حكم أخلاقي.'),

    jsonb_build_object('type','heading','level',3,'text','من الهدف إلى خطوة قابلة للمتابعة'),
    jsonb_build_object('type','paragraph','text','يمكن صياغة الخطوة بحيث تكون محددة وقابلة للملاحظة وواقعية ومرتبطة بهدف الشخص ومحددة بوقت تقريبي، مع مرونة عند تغير الظروف. مثال مؤسسي آمن: إذا كان الهدف تحسين استمرارية العلاج، يمكن أن تكون الخطوة التأكد من الموعد القادم ووسيلة النقل والجهة التي يتصل بها الشخص إذا تعذر الحضور. لا يحتاج العامل بالأقران إلى تفسير الدواء أو تغييره؛ دوره هنا إزالة العائق وربط الشخص بالمختص المسؤول.'),

    jsonb_build_object('type','heading','level',2,'text','4. ماذا يفعل العامل بالأقران عمليًا؟'),
    jsonb_build_object('type','paragraph','text','قد تشمل الوظائف الاستماع، مشاركة خبرة معيشة بقدر يخدم الشخص، مساعدة عملية، بناء أمل واقعي، استكشاف نقاط القوة، التعريف بالخيارات، مرافقة انتقال إلى خدمة، دعم مهارات الدفاع عن النفس، ربط السكن والعمل والتعليم والمجموعات والخدمات، والمتابعة بعد الانقطاع. يمكنه كذلك مساعدة الشخص على الاستعداد لسؤال الطبيب أو المعالج وتدوين ما يريد مناقشته. القيمة ليست في امتلاك إجابة لكل شيء، بل في معرفة متى يساعد مباشرة ومتى يربط ومتى يستشير مشرفًا.'),
    jsonb_build_object('type','paragraph','text','في الانتقالات عالية الفقد مثل الخروج من الطوارئ أو العلاج الداخلي أو السجن، يستطيع العامل بالأقران أن يدعم ما يسمى الانتقال الدافئ: التأكد من فهم الخطوة التالية، الاتصال بالجهة، حل عائق نقل أو أوراق، ومتابعة ما إذا اكتمل الوصول. في الرعاية الأولية يمكنه تقليل الوصمة وشرح أن العلاج الدوائي لاضطراب استخدام الأفيونات أحد مسارات التعافي المشروعة، دون أن يتحول إلى واصف دواء أو مستشار جرعات.'),

    jsonb_build_object('type','heading','level',2,'text','5. حدود الدور: متى يجب التوقف عن المساعدة المباشرة والإحالة؟'),
    jsonb_build_object('type','paragraph','text','الحدود المهنية تحمي الجميع. لا يشخص العامل بالأقران اضطرابًا، ولا يقرر تغيير دواء، ولا يدير انسحابًا طبيًا، ولا يعد بنتيجة، ولا يحتفظ بأسرار تهدد حياة شخص إذا كانت سياسة الخدمة والقانون يفرضان تصعيدًا محددًا. كما لا يستخدم المال أو السكن أو العلاقات الشخصية لإنشاء تبعية، ولا يجعل استمرار العلاقة مرتبطًا بموافقة الشخص على نصيحته. يجب أن تعرف المؤسسة مسبقًا حالات التصعيد ومسار التواصل مع المشرف أو الفريق السريري والطوارئ المحلية.'),
    jsonb_build_object('type','paragraph','text','الموقف الصعب ليس دائمًا أزمة. قد يختلف العامل والشخص حول هدف أو مجموعة دعم أو دواء أو إشراك الأسرة. الأصل هو العودة إلى تفضيل الشخص والمعلومات الموثوقة وحدود السلامة. إذا كان العامل لا يعرف الإجابة، فإن قول لا أعرف وسأساعدك في الوصول إلى المصدر المناسب ممارسة مهنية أقوى من تقديم رأي شخصي بلهجة يقين.'),

    jsonb_build_object('type','heading','level',3,'text','مشاركة قصة التعافي: أداة وليست مركز الجلسة'),
    jsonb_build_object('type','paragraph','text','القصة الشخصية مفيدة عندما تقلل العزلة أو توضح أن التغيير ممكن أو تفتح خيارًا لم يره الشخص، لكنها تصبح عبئًا عندما يضطر المستفيد إلى الاستماع طويلًا أو يشعر أن نجاحه سيقاس بنسخ مسار العامل. قبل المشاركة يمكن سؤال: هل هذه المعلومة تخدم هدف الشخص الآن؟ هل تكشف تفاصيل لا أريد أن تصبح جزءًا من العلاقة المهنية؟ هل ستترك مساحة لخبرته المختلفة؟ الكفاءة هنا في اختيار ما لا يُقال بقدر اختيار ما يُقال.'),

    jsonb_build_object('type','heading','level',2,'text','6. الخصوصية والثقة والعلاقات المزدوجة'),
    jsonb_build_object('type','paragraph','text','قد يعمل العامل بالأقران في مجتمع صغير يعرف فيه المستفيد اجتماعيًا أو عائليًا. ينبغي للمؤسسة أن تملك سياسة للعلاقات المزدوجة والخصوصية والتواصل خارج ساعات الخدمة والمنصات الرقمية والهدايا والنقل والمال. لا تكفي عبارة حافظ على السرية؛ يحتاج العامل أمثلة ومشرفًا يمكن الرجوع إليه. ويجب شرح حدود الخصوصية للمستفيد في بداية العلاقة بلغة يفهمها، بما في ذلك الحالات التي يفرض فيها القانون أو السلامة مشاركة معلومات محددة.'),
    jsonb_build_object('type','paragraph','text','التوثيق أيضًا يحتاج حدًا مناسبًا. سجل ما يلزم لاستمرارية الخدمة والسلامة والهدف، لا كل تفاصيل القصة الشخصية. إذا كان برنامج الأقران جزءًا من فريق أكبر، يجب تحديد ما الذي يراه بقية الفريق وكيف تستخدم المعلومات. الإفراط في التوثيق يمكن أن يضعف الثقة، ونقصه قد يعرقل الاستمرارية؛ الحل هو سياسة واضحة وموافقة مفهومة وتدريب.'),

    jsonb_build_object('type','heading','level',2,'text','7. المجموعات والمساندة المتبادلة: مسارات متعددة لا مجموعة واحدة للجميع'),
    jsonb_build_object('type','paragraph','text','يمكن أن تضيف مجموعات المساندة المتبادلة انتماءً وروتينًا ونماذج أمل وعلاقات خارج بيئات الاستخدام. توجد مسارات روحية وعلمانية ومجموعات موجهة لأسر أو فئات أو مواد أو أهداف مختلفة. ينبغي إعطاء الشخص معلومات وخيارات بدل افتراض أن برنامجًا واحدًا يناسب الجميع. NICE يوصي بإعطاء معلومات عن مجموعات المساعدة الذاتية وتسهيل الاتصال لمن يرغب، لكن اختيار المجموعة واستمرارها يظلان قرارًا شخصيًا.'),
    jsonb_build_object('type','paragraph','text','على المؤسسة مراجعة سلامة أي مجموعة توصي بها: هل تحترم العلاج الدوائي؟ هل توجد حدود للتحرش أو الاستغلال؟ هل تتاح للأشخاص ذوي الاحتياجات الخاصة؟ هل تحمي الخصوصية؟ هل الخطاب غير وصمي؟ المجموعة المجتمعية ليست معفاة من معايير السلامة لمجرد أنها مجانية أو قائمة على التطوع. كما أن عدم رغبة الشخص في مجموعة لا يعني غياب الدافعية؛ يمكن بناء رأس مال اجتماعي عبر طرق أخرى.'),

    jsonb_build_object('type','heading','level',2,'text','8. دعم الأقران الرقمي وعن بعد'),
    jsonb_build_object('type','paragraph','text','يمكن للدعم عبر الهاتف أو الفيديو أو الرسائل أن يقلل عبء النقل ويزيد الوصول في المناطق البعيدة أو لمن يصعب عليهم الحضور، لكنه يضيف أسئلة عن الخصوصية والهوية وساعات الاستجابة وحدود الأزمة والوصول الرقمي. يجب أن يعرف المستخدم هل القناة مراقبة باستمرار أم في أوقات محددة، وما الذي يحدث إذا أرسل رسالة عن خطر عاجل، وأين تُحفظ البيانات. الخدمة الرقمية ليست خط طوارئ لمجرد أنها متاحة على الهاتف.'),
    jsonb_build_object('type','paragraph','text','التصميم الميسر مهم: نص واضح، توافق مع قارئات الشاشة، ترجمة أو تواصل بديل عند الحاجة، بديل لمن لا يملك اتصالًا جيدًا، وعدم افتراض أن كل شخص يملك مساحة خاصة للمكالمة. يمكن استخدام التقنية للمتابعة وبناء الروتين والوصول إلى الموارد، مع بقاء اللقاء الحضوري أو السريري ضروريًا في حالات تتطلب فحصًا أو تقييمًا لا يمكن إنجازه بأمان عن بعد.'),

    jsonb_build_object('type','heading','level',3,'text','كيف تمنع المؤسسة أن يتحول الاتصال الرقمي إلى دوام دائم؟'),
    jsonb_build_object('type','paragraph','text','تحدد المؤسسة قنوات الاتصال وساعاتها والمدة المتوقعة للرد والبديل خارج الدوام، وتدرب العامل على عدم استخدام حساباته الشخصية إذا كانت السياسة تمنع ذلك. كما توزع العبء بحيث لا يصبح عامل واحد نقطة الاتصال الوحيدة لشخص أو مجموعة كبيرة. حماية رفاه العامل جزء من سلامة الخدمة؛ الإرهاق والاتصال المستمر يمكن أن يضعفا الحكم والحدود ويزيدا دوران القوى العاملة.'),

    jsonb_build_object('type','heading','level',2,'text','9. تدريب وإشراف العاملين بالأقران'),
    jsonb_build_object('type','paragraph','text','الكفاءة لا تُبنى بدورة أولية فقط. يحتاج العامل إلى تدريب على مبادئ التعافي، التواصل، الأخلاقيات، الخصوصية، التوثيق، الحدود، التنوع والإتاحة، فهم منظومة العلاج، التصعيد في الأزمات، ومهارات الربط بالموارد، ثم إشراف مستمر يناسب طبيعة الدور. توضح SAMHSA أن الكفاءات يمكن أن توجه التدريب والشهادات والوصف الوظيفي وتقييم الأداء، وليست حاجزًا لإقصاء من يدخل المهنة.'),
    jsonb_build_object('type','paragraph','text','المشرف يحتاج فهمًا لدور الأقران نفسه؛ الإشراف السريري التقليدي الذي يطلب من العامل أن يصبح نسخة من المعالج قد يمحو القيمة الفريدة للخبرة المعيشة، بينما غياب الإشراف يترك العامل وحيدًا أمام مواقف معقدة. الإشراف الجيد يراجع الحدود، القرارات الصعبة، العبء العاطفي، جودة الربط، التعلم، والحاجة إلى دعم العامل، دون استخدام قصة العامل الشخصية كملف علاجي داخل مكان العمل.'),

    jsonb_build_object('type','heading','level',2,'text','10. دمج الأقران في العلاج دون تهميش أو استخدام رمزي'),
    jsonb_build_object('type','paragraph','text','وجود عامل بالأقران في الفريق لا يكفي إذا لم يعرف بقية الفريق صلاحياته أو إذا حُصر في النقل والأعمال الأقل قيمة. ينبغي تحديد الدور ومسار الإحالة والوصول إلى الاجتماعات والمعلومات الضرورية والإشراف والتعويض وفرص التقدم المهني. وفي المقابل لا ينبغي تحميل العامل مهام سريرية بلا تدريب أو حماية لمجرد نقص القوى العاملة. الدمج الحقيقي يعترف بخبرة معيشة بوصفها خبرة مهنية مختلفة ومكملة.'),
    jsonb_build_object('type','paragraph','text','يمكن إشراك الأقران أيضًا في تصميم الخدمات وتقييمها وتدريب العاملين ومراجعة اللغة والسياسات. فهمهم لنقاط الانقطاع والوصمة والعوائق العملية قد يكشف مشكلات لا تظهر في لوحات البيانات. لكن المشاركة يجب أن تكون مدفوعة أو معترفًا بها بصورة عادلة عندما تكون عملًا مستمرًا، وألا تطلب المؤسسة من شخص كشف تفاصيل حساسة ليبرهن على أهليته للمساهمة.'),

    jsonb_build_object('type','heading','level',2,'text','11. كيف نقيس أثر دعم الأقران ورأس مال التعافي؟'),
    jsonb_build_object('type','paragraph','text','القياس لا ينبغي أن يعتمد على ادعاء أن خدمة الأقران تمنع كل عودة للاستخدام. يمكن قياس الوصول والبدء والاستمرار في الخدمة، إكمال الإحالات، البقاء في العلاج، الرضا والثقة، الشعور بالاتصال والأمل والقدرة على طلب المساعدة، استقرار السكن، المشاركة في التعليم أو العمل، وتحسن الموارد التي اختار الشخص العمل عليها. عندما يقاس رأس مال التعافي، يجب استخدامه لفهم التغير والتخطيط لا لترتيب الناس أو حرمان أصحاب الدرجات المنخفضة من خدمة.'),
    jsonb_build_object('type','paragraph','text','على البرنامج أن يفصل بين نشاط العامل والنتيجة التي قد تتأثر بعوامل كثيرة. إذا رافق العامل شخصًا إلى موعد لكنه لم يجد موعدًا متاحًا، فهذه مشكلة نظام لا فشل عامل أو مستفيد. وإذا تحسن الحضور بعد إضافة خدمة أقران، يمكن دراسة المساهمة مع بيانات أخرى بدل نسبة السببية مباشرة. الجمع بين مؤشرات كمية وتجربة المستخدم والعامل يعطي صورة أكثر عدلًا.'),

    jsonb_build_object('type','heading','level',3,'text','مؤشرات جودة على مستوى المؤسسة'),
    jsonb_build_object('type','list','ordered',false,'items',jsonb_build_array(
      'نسبة من عُرضت عليهم خدمة الأقران طوعًا ومن اختاروها فعلًا.',
      'زمن الوصول إلى أول اتصال ومدى اختلافه بين المناطق والفئات.',
      'نسبة الإحالات التي اكتملت إلى علاج أو سكن أو عمل أو خدمة أخرى.',
      'معدلات الاستمرار والانقطاع وأسباب الانقطاع من منظور المستخدم.',
      'وجود إشراف منتظم وتدريب مستمر وحوادث حدود أو خصوصية وكيف عولجت.',
      'رفاه العاملين ودورانهم وعبء الحالات وفرص التطور الوظيفي.',
      'مشاركة الأقران في تحسين السياسات والخدمات لا تقديم الدعم الفردي فقط.'
    )),

    jsonb_build_object('type','heading','level',2,'text','12. خريطة قرار لاستخدام دعم الأقران'),
    jsonb_build_object('type','paragraph','text','إذا كان الشخص في خطر طبي أو نفسي فوري، يتجه المسار إلى الخدمة الطارئة أو السريرية المناسبة ويعمل القرين على الدعم والربط ضمن حدوده. إذا كان العلاج مناسبًا لكنه صعب الوصول، يمكن للقرين العمل على العوائق والانتقال والمتابعة. إذا كان الشخص مستقرًا سريريًا لكنه معزول أو بلا روتين أو سكن أو عمل، تصبح خريطة رأس مال التعافي أكثر مركزية. وإذا كان الهدف الانتماء أو المعنى، يمكن استكشاف مجموعات أو أنشطة أو أدوار مجتمعية يختارها الشخص.'),
    jsonb_build_object('type','paragraph','text','للأسرة، يمكن دعم وصول الشخص إلى قرين إذا أراد، كما يمكن أن توجد خدمات أقران أسرية منفصلة تركز على احتياجات أفراد الأسرة أنفسهم. للمؤسسة، يبدأ القرار بتحديد الحاجة والدور والتدريب والإشراف والخصوصية والتعويض والمسار السريري عند تجاوز حدود الدور. أفضل خدمة أقران ليست التي تفعل كل شيء، بل التي تعرف قيمتها وحدودها وتعمل داخل منظومة يستطيع الشخص التحرك فيها دون أن يفقد صوته.'),
    jsonb_build_object('type','paragraph','text','رأس مال التعافي يضيف معيارًا مهمًا للمرجع العربي: لا نسأل فقط هل توقف الاستخدام؟ بل هل أصبحت الحياة أكثر قدرة على حمل التعافي؟ هل توجد رعاية يمكن الوصول إليها، علاقة آمنة، مكان للنوم، طريق إلى العمل أو الدراسة، مهارات لطلب المساعدة، وشعور بأن المستقبل قابل للبناء؟ عندما تتحسن هذه البنية، تصبح الخطة أقل اعتمادًا على قوة الإرادة في لحظة ضغط وأكثر اعتمادًا على شبكة موارد متاحة وقابلة للنمو.'),

    jsonb_build_object('type','faq','items',jsonb_build_array(
      jsonb_build_object('question','ما الفرق بين العامل بالأقران والمعالج النفسي؟','answer','العامل بالأقران يستخدم خبرة معيشة وتدريبًا لدعم الأمل والأهداف والربط والمهارات العملية، بينما المعالج يعمل ضمن مؤهل سريري لتقييم وعلاج مشكلات نفسية. قد يعمل الاثنان معًا، لكن لا ينبغي مطالبة القرين بالتشخيص أو وصف العلاج ما لم يحمل مؤهلًا مستقلًا لذلك.'),
      jsonb_build_object('question','ما معنى رأس مال التعافي؟','answer','هو الموارد الشخصية والاجتماعية والمادية والمجتمعية التي يستطيع الشخص استخدامها لبدء التعافي واستمراره، مثل الصحة والسكن والعلاقات والمهارات والعمل والانتماء والخدمات. هو إطار لبناء الموارد وليس درجةً لتحديد من يستحق العلاج.'),
      jsonb_build_object('question','هل يجب أن يكون العامل بالأقران متعافيًا بالطريقة نفسها التي أريدها؟','answer','لا. التشابه في الخبرة قد يساعد على التواصل، لكن الخدمة الجيدة تحترم تعدد مسارات التعافي ولا تفرض تجربة العامل. الأهم قدرته على الاستماع واحترام أهدافك وحدوده وربطك بخيارات مناسبة.'),
      jsonb_build_object('question','هل يمكن للعامل بالأقران أن ينصحني بإيقاف دواء؟','answer','لا ينبغي أن يقدم قرارًا دوائيًا خارج اختصاص مؤهل مستقل. يستطيع مساعدتك على تدوين أسئلتك والوصول إلى الواصف ومناقشة العوائق أو الوصمة المرتبطة بالعلاج، بينما يبقى القرار الدوائي مع الفريق المؤهل.'),
      jsonb_build_object('question','هل مجموعات التعافي إلزامية؟','answer','لا ينبغي افتراض أن مجموعة واحدة تناسب الجميع. توجد مسارات متعددة ويمكن للشخص اختيار مجموعة أو نشاط أو شبكة دعم أخرى. دور الخدمة هو عرض خيارات موثوقة وتسهيل الاتصال إذا أراد الشخص.'),
      jsonb_build_object('question','هل دعم الأقران مفيد بعد انتهاء العلاج؟','answer','نعم، يمكن أن يكون مفيدًا في الانتقال إلى الحياة اليومية وبناء السكن والعمل والعلاقات والروتين والانتماء واستعادة الاتصال بالخدمات عند التعثر. مقدار الدعم ومدته يعتمدان على أهداف الشخص والبرنامج.'),
      jsonb_build_object('question','كيف أعرف أن برنامج دعم الأقران مهني؟','answer','ابحث عن وصف دور واضح، مشاركة طوعية، تدريب وكفاءات، إشراف، سياسات خصوصية وحدود، مسار للتصعيد عند الحالات السريرية، وقياس نتائج مثل الوصول والربط والاستمرار ورفاه المستخدم والعامل.'),
      jsonb_build_object('question','هل يمكن أن يكون أحد أفراد الأسرة عامل دعم أقران؟','answer','توجد أدوار مهنية لدعم الأقران الأسري تعتمد على خبرة الأسرة وتدريبها، لكنها تختلف عن كون القريب نفسه مقدم الدعم الرئيسي للشخص. لكل دور حدود وخصوصية وأهداف، وقد تحتاج الأسرة خدمة مستقلة لصحتها واحتياجاتها.'),
      jsonb_build_object('question','ماذا أفعل إذا تجاوز عامل بالأقران حدوده أو ضغط علي؟','answer','يمكنك إيقاف أو تعديل المشاركة وطلب مشرف أو قناة شكوى وفق الخدمة. المشاركة يفترض أن تكون طوعية ومتمحورة حول أهدافك، ولا ينبغي استخدام العلاقة لفرض علاج أو علاقة شخصية أو تبادل مالي خارج السياسات.')
    ))
